// Some portions generated by Codex

const { test, expect } = require('@playwright/test');
const fs = require('node:fs');
const path = require('node:path');
const {
	deleteRepository,
	memoryRepositoryConfiguration,
	openQueryPage,
	repositoryPageUrl,
	runQuery,
	serverBaseUrl,
	setQueryEditor,
	uniqueRepositoryId,
	waitForRoute,
	waitForWriteDone,
	workbenchBaseUrl
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-bnr');
const REPOSITORY_URL = `${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}`;
const FIXED_ID = 'workbench-bnr-fixed';
const OTHER_ID = 'workbench-bnr-other';
const GRAPH_ID = 'workbench-bnr-graph';
const SPECIAL_ID = '_:space > backslash\\ percent% Unicode-π';
const SPECIAL_REF = '<_:_:space\\u0020\\u003E\\u0020backslash\\u005C\\u0020percent%\\u0020Unicode-π>';
const EVIDENCE_DIRECTORY = '/tmp/rdf4j-workbench-bnr-evidence';
let fixtureCreated = false;

test.describe.configure({ mode: 'serial' });

async function installClipboardRecorder(page) {
	const writes = [];
	await page.exposeFunction('__recordBnrClipboardWrite', value => {
		writes.push(value);
	});
	await page.addInitScript(() => {
		Object.defineProperty(navigator, 'clipboard', {
			configurable: true,
			value: { writeText: value => window.__recordBnrClipboardWrite(value) }
		});
	});
	return writes;
}

test.beforeAll(async ({ request }) => {
	const existing = await request.get(`${REPOSITORY_URL}/config`);
	if (existing.status() !== 404) {
		throw new Error(`Refusing to use non-absent disposable repository ${REPOSITORY_ID}: `
			+ `GET config ${existing.status()}`);
	}
	const created = await request.put(REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Workbench blank node reference fixture')
	});
	if (![200, 201, 204].includes(created.status())) {
		throw new Error(`Creating repository ${REPOSITORY_ID} failed with HTTP ${created.status()}`);
	}
	fixtureCreated = true;
});

test.afterAll(async ({ request }) => {
	if (!fixtureCreated) {
		return;
	}
	if (process.env.WORKBENCH_BNR_RETAIN_FIXTURE === 'true') {
		const retained = await request.get(`${REPOSITORY_URL}/config`);
		if (retained.status() !== 200) {
			throw new Error(`Retained repository ${REPOSITORY_ID} is unavailable: GET config ${retained.status()}`);
		}
		console.info(`Retained Workbench blank node reference fixture: ${REPOSITORY_URL}`);
		return;
	}
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function submitUpdate(page, update) {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'update'), { waitUntil: 'networkidle' });
	await page.locator('#update-editor .CodeMirror').waitFor({ state: 'visible' });
	await setQueryEditor(page, update);
	await page.locator('#update-form input[type="submit"]').click();
	await waitForWriteDone(page, 'update');
}

async function queryEditorValue(page) {
	return page.locator('.query-page .CodeMirror').first().evaluate(element => element.CodeMirror.getValue());
}

function queryRows(page) {
	return page.locator('#query-results table.data tbody tr[data-query-row-index]');
}

function exploreRoleRows(page, role) {
	return page.locator(`#explore-results [data-explore-role="${role}"] table.data tbody tr[data-workbench-row-index]`);
}

function monitorBrowser(page) {
	const health = { pageErrors: [], consoleErrors: [], httpErrors: [], requestFailures: [] };
	page.on('pageerror', error => health.pageErrors.push(error.message));
	page.on('console', message => {
		if (message.type() === 'error') {
			health.consoleErrors.push(message.text());
		}
	});
	page.on('response', response => {
		if (response.status() >= 400) {
			const url = new URL(response.url());
			health.httpErrors.push({
				method: response.request().method(),
				path: url.pathname,
				status: response.status()
			});
		}
	});
	page.on('requestfailed', request => health.requestFailures.push({
		method: request.method(),
		url: request.url(),
		failure: request.failure()?.errorText || 'unknown request failure'
	}));
	return health;
}

function browserEvidenceName(name) {
	return `${test.info().project.name}-${name}`;
}

async function assertBrowserHealthy(page, health, name, expectedErrorResponses = []) {
	await expect(page.locator('#workbench-app')).toBeVisible();
	const outlet = page.locator('#workbench-outlet[data-workbench-route-ready="true"]');
	await expect(outlet).toBeVisible();
	expect((await outlet.innerText()).trim().length, 'the Workbench route must not be blank').toBeGreaterThan(0);
	expect(new URL(page.url()).pathname).toContain(`/repositories/${REPOSITORY_ID}/`);
	await expect(page.locator('dialog.workbench-dialog[open]')).toHaveCount(0);
	const healthDirectory = path.join(EVIDENCE_DIRECTORY, 'browser-health');
	fs.mkdirSync(healthDirectory, { recursive: true });
	fs.writeFileSync(path.join(healthDirectory, `${browserEvidenceName(name)}.json`), JSON.stringify({
		url: page.url(),
		pageErrors: health.pageErrors,
		consoleErrors: health.consoleErrors,
		httpErrors: health.httpErrors,
		requestFailures: health.requestFailures
	}, null, 2) + '\n');
	expect(health.pageErrors, 'the page must not raise JavaScript exceptions').toEqual([]);
	const isExpectedErrorResponse = response => expectedErrorResponses.some(expected =>
		response.method === expected.method && response.path.endsWith(expected.pathSuffix)
		&& response.status === expected.status);
	expect(health.httpErrors.filter(response => !isExpectedErrorResponse(response)), 'unexpected HTTP error responses')
		.toEqual([]);
	const workbenchRepositoryPrefix = new URL(
		`repositories/${REPOSITORY_ID}/`, `${workbenchBaseUrl()}/`).pathname;
	const isExpectedRouteAbort = failure => failure.failure === 'net::ERR_ABORTED'
		&& new URL(failure.url).origin === new URL(workbenchBaseUrl()).origin
		&& new URL(failure.url).pathname.startsWith(workbenchRepositoryPrefix);
	// WebKit may report the malformed query body as cancelled after the expected HTTP 400 has rendered its error.
	const isExpectedErrorCancellation = failure => failure.failure === 'cancelled'
		&& expectedErrorResponses.some(expected => {
			const url = new URL(failure.url);
			return failure.method === expected.method && url.pathname.endsWith(expected.pathSuffix)
				&& expected.status === 400 && health.httpErrors.some(response => response.method === expected.method
					&& response.path.endsWith(expected.pathSuffix) && response.status === expected.status);
		});
	// Workbench navigation cancels in-flight requests to the old repository route; retain these in the health artifact.
	expect(health.requestFailures.filter(failure => !isExpectedRouteAbort(failure)
		&& !isExpectedErrorCancellation(failure)), 'unexpected browser request failures')
		.toEqual([]);
	const unexpectedConsoleErrors = health.consoleErrors.filter(message => {
		if (!message.startsWith('Failed to load resource:')) {
			return true;
		}
		return !health.httpErrors.some(isExpectedErrorResponse);
	});
	expect(unexpectedConsoleErrors, 'unexpected browser console errors').toEqual([]);
}

async function captureScreenshot(page, name) {
	const screenshotDirectory = path.join(EVIDENCE_DIRECTORY, 'screenshots');
	fs.mkdirSync(screenshotDirectory, { recursive: true });
	await page.screenshot({ path: path.join(screenshotDirectory, `${browserEvidenceName(name)}.png`), fullPage: true });
}

test('Workbench query results explore and copy a reusable fixed blank node reference', async ({ page }) => {
	const health = monitorBrowser(page);
	const clipboardWrites = await installClipboardRecorder(page);

	await submitUpdate(page, `INSERT DATA {
		<_:${FIXED_ID}> <urn:bnr:predicate> "fixed subject" .
		<urn:bnr:other-subject> <urn:bnr:object> <_:${FIXED_ID}> .
		<_:${OTHER_ID}> <urn:bnr:predicate> "other subject" .
	}`);

	await openQueryPage(page, REPOSITORY_ID);
	await runQuery(page, `SELECT ?p ?o WHERE { <_:${FIXED_ID}> ?p ?o }`);
	await expect(queryRows(page)).toHaveCount(1);
	await expect(queryRows(page).first()).toContainText('fixed subject');

	await runQuery(page, 'SELECT ?p ?o WHERE { _:existential ?p ?o }');
	const existentialRows = await queryRows(page).allTextContents();
	expect(existentialRows).toHaveLength(3);
	expect(existentialRows.join('\n')).toContain('fixed subject');
	expect(existentialRows.join('\n')).toContain('other subject');

	await runQuery(page, `SELECT ?s WHERE { ?s <urn:bnr:predicate> "fixed subject" }`);
	const resourceLink = queryRows(page).first().locator('td a').first();
	await expect(resourceLink).toBeVisible();
	await resourceLink.click();
	await waitForRoute(page, 'explore');
	await expect(page.locator('#explore-resource-card')).toBeVisible();
	await page.locator('#explore-resource-card button[aria-label="Copy resource"]').click();
	await expect.poll(() => clipboardWrites).toEqual([`<_:${FIXED_ID}>`]);
	await expect(page.locator('#explore-resource-iri')).toHaveText(`<_:${FIXED_ID}>`);
	const queryResourceLink = page.locator('#explore-resource-card a.explore-resource-card__query');
	await expect(queryResourceLink).toBeVisible();
	const queryHref = await queryResourceLink.getAttribute('href');
	const resourceQuery = new URL(queryHref, workbenchBaseUrl()).searchParams.get('query');
	expect(resourceQuery).toBe(`SELECT * WHERE { <_:${FIXED_ID}> ?p ?o }`);
	await queryResourceLink.click();
	await waitForRoute(page, 'query');
	expect(await queryEditorValue(page)).toBe(resourceQuery);
	await runQuery(page, resourceQuery);
	await expect(queryRows(page)).toHaveCount(1);
	await expect(queryRows(page).first().locator('td').nth(0)).toContainText('urn:bnr:predicate');
	await expect(queryRows(page).first().locator('td').nth(1)).toContainText('fixed subject');
	await captureScreenshot(page, 'query-fixed-reference-result');
	await assertBrowserHealthy(page, health, 'fixed-reference-query');
});

test('Workbench preserves escaped IDs, graph roles, nested triples, and graph-result Explore links', async ({ page }) => {
	const health = monitorBrowser(page);
	const clipboardWrites = await installClipboardRecorder(page);
	const nestedTripleReference = `<<( ${SPECIAL_REF} <urn:bnr:nested> "quoted" )>>`;
	await submitUpdate(page, `INSERT DATA {
		${SPECIAL_REF} <urn:bnr:predicate> "special subject" .
		<urn:bnr:special-object-subject> <urn:bnr:object> ${SPECIAL_REF} .
		GRAPH <_:${GRAPH_ID}> {
			${SPECIAL_REF} <urn:bnr:predicate> ${nestedTripleReference} .
		}
	}`);

	await openQueryPage(page, REPOSITORY_ID);
	await runQuery(page, `SELECT ?p ?o WHERE { ${SPECIAL_REF} ?p ?o }`);
	// Unqualified patterns use the repository's union-default dataset, so the subject occurs in two graphs.
	await expect(queryRows(page)).toHaveCount(2);
	const unionRows = await queryRows(page).allTextContents();
	expect(unionRows.join('\n')).toContain('special subject');
	expect(unionRows.join('\n')).toContain('quoted');
	expect(unionRows.join('\n')).toContain(SPECIAL_REF);

	await runQuery(page, `SELECT ?s WHERE { ?s <urn:bnr:object> ${SPECIAL_REF} }`);
	await expect(queryRows(page)).toHaveCount(1);
	await expect(queryRows(page).first()).toContainText('urn:bnr:special-object-subject');

	await runQuery(page, `SELECT ?g ?o WHERE {
		GRAPH ?g { ${SPECIAL_REF} <urn:bnr:predicate> ?o }
	}`);
	await expect(queryRows(page)).toHaveCount(1);
	await expect(queryRows(page).first().locator('td').nth(0)).toHaveText(`<_:${GRAPH_ID}>`);
	await expect(queryRows(page).first().locator('td').nth(1)).toContainText('quoted');
	await expect(queryRows(page).first().locator('td').nth(1)).toContainText(SPECIAL_REF);

	await runQuery(page, `SELECT ?s WHERE { ?s <urn:bnr:predicate> "special subject" }`);
	const specialResourceLink = queryRows(page).first().locator('td a').first();
	await expect(specialResourceLink).toBeVisible();
	await expect(specialResourceLink).toHaveText(SPECIAL_REF);
	const specialExploreUrl = new URL(await specialResourceLink.getAttribute('href'), page.url());
	expect(specialExploreUrl.searchParams.get('resource')).toBe(SPECIAL_REF);
	await specialResourceLink.click();
	await waitForRoute(page, 'explore', { url: specialExploreUrl.href });
	await expect(page.locator('#resource')).toHaveValue(SPECIAL_REF);

	const outgoingRows = exploreRoleRows(page, 'outgoing');
	await expect(outgoingRows).toHaveCount(2);
	const defaultSubjectRow = outgoingRows.filter({ hasText: 'special subject' });
	await expect(defaultSubjectRow).toHaveCount(1);
	await expect(defaultSubjectRow.locator('td[data-label="Predicate"]')).toContainText('urn:bnr:predicate');
	const nestedTripleRow = outgoingRows.filter({ hasText: 'quoted' });
	await expect(nestedTripleRow).toHaveCount(1);
	const nestedTripleCell = nestedTripleRow.locator('td[data-label="Object"]');
	await expect(nestedTripleCell).toContainText(SPECIAL_REF);
	await expect(nestedTripleCell).toContainText('urn:bnr:nested');
	await expect(nestedTripleCell).toContainText('quoted');
	await expect(nestedTripleRow.locator('td[data-label="Graph"]')).toHaveText(`<_:${GRAPH_ID}>`);
	const incomingRows = exploreRoleRows(page, 'incoming');
	await expect(incomingRows).toHaveCount(1);
	await expect(incomingRows.first().locator('td[data-label="Subject"]')).toContainText('urn:bnr:special-object-subject');
	await expect(incomingRows.first().locator('td[data-label="Predicate"]')).toContainText('urn:bnr:object');
	await captureScreenshot(page, 'special-node-explore');

	await page.locator('#explore-resource-card button[aria-label="Copy resource"]').click();
	await expect.poll(() => clipboardWrites).toEqual([SPECIAL_REF]);
	const queryResourceLink = page.locator('#explore-resource-card a.explore-resource-card__query');
	await expect(queryResourceLink).toBeVisible();
	const resourceQuery = new URL(await queryResourceLink.getAttribute('href'), workbenchBaseUrl()).searchParams.get('query');
	expect(resourceQuery).toBe(`SELECT * WHERE { ${SPECIAL_REF} ?p ?o }`);

	const nestedTripleLink = nestedTripleCell.locator('a').first();
	await expect(nestedTripleLink).toBeVisible();
	const nestedExploreUrl = new URL(await nestedTripleLink.getAttribute('href'), page.url());
	expect(nestedExploreUrl.searchParams.get('resource')).toBe(nestedTripleReference);
	await nestedTripleLink.click();
	await waitForRoute(page, 'explore', { url: nestedExploreUrl.href });
	await expect(page.locator('#resource')).toHaveValue(nestedTripleReference);
	const nestedIncomingRows = exploreRoleRows(page, 'incoming');
	await expect(nestedIncomingRows).toHaveCount(1);
	await expect(nestedIncomingRows.first().locator('td[data-label="Subject"]')).toContainText(SPECIAL_REF);
	await expect(nestedIncomingRows.first().locator('td[data-label="Predicate"]')).toContainText('urn:bnr:predicate');

	// Reuse the value actually written by Copy. Deleting this exact reference must leave the other same-predicate
	// blank node intact.
	const copiedSpecialReference = clipboardWrites[0];
	await submitUpdate(page, `DELETE DATA { ${copiedSpecialReference} <urn:bnr:predicate> "special subject" . }`);
	await openQueryPage(page, REPOSITORY_ID);
	await runQuery(page, `SELECT ?o WHERE { <_:${OTHER_ID}> <urn:bnr:predicate> ?o }`);
	await expect(queryRows(page)).toHaveCount(1);
	await expect(queryRows(page).first()).toContainText('other subject');
	await captureScreenshot(page, 'query-unrelated-bnode-preserved');

	// A CONSTRUCT result is a separate graph-result path: its BNode link must still explore the original resource.
	await runQuery(page, `CONSTRUCT { ${SPECIAL_REF} <urn:bnr:constructed> ?o } WHERE {
		GRAPH <_:${GRAPH_ID}> { ${SPECIAL_REF} <urn:bnr:predicate> ?o }
	}`);
	const constructedRows = page.locator('#query-results .query-result-table-wrap table.data tbody tr');
	await expect(constructedRows).toHaveCount(1);
	const constructedSubjectLink = constructedRows.first().locator('td[data-label="subject"] a').first();
	await expect(constructedSubjectLink).toHaveText(SPECIAL_REF);
	const constructedExploreUrl = new URL(await constructedSubjectLink.getAttribute('href'), page.url());
	expect(constructedExploreUrl.searchParams.get('resource')).toBe(SPECIAL_REF);
	await captureScreenshot(page, 'query-construct-special-reference');
	await constructedSubjectLink.click();
	await waitForRoute(page, 'explore', { url: constructedExploreUrl.href });
	await expect(page.locator('#resource')).toHaveValue(SPECIAL_REF);
	const constructedExploreRows = exploreRoleRows(page, 'outgoing');
	await expect(constructedExploreRows).toHaveCount(1);
	await expect(constructedExploreRows.first().locator('td[data-label="Object"]')).toContainText('quoted');
	await captureScreenshot(page, 'special-node-explore-after-construct');
	await assertBrowserHealthy(page, health, 'construct-result-explore-desktop');

	const mobilePage = await page.context().newPage();
	const mobileHealth = monitorBrowser(mobilePage);
	await mobilePage.setViewportSize({ width: 390, height: 844 });
	await mobilePage.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(SPECIAL_REF)}`,
		{ waitUntil: 'domcontentloaded' });
	await waitForRoute(mobilePage, 'explore');
	await expect(mobilePage.locator('#resource')).toHaveValue(SPECIAL_REF);
	await expect(mobilePage.locator('#explore-results [data-explore-role="outgoing"]')).toContainText('quoted');
	await expect(mobilePage.locator('#explore-results [data-explore-role="incoming"]'))
		.toContainText('urn:bnr:special-object-subject');
	await captureScreenshot(mobilePage, 'special-node-explore-mobile');
	await assertBrowserHealthy(mobilePage, mobileHealth, 'special-node-explore-mobile');
	await mobilePage.close();
});

test('Chromium Clipboard API returns the copied fixed blank node reference', async ({ browserName, page }) => {
	test.skip(browserName !== 'chromium', 'Clipboard API permission smoke runs in Chromium');
	const health = monitorBrowser(page);
	const origin = new URL(workbenchBaseUrl()).origin;
	await page.context().grantPermissions(['clipboard-read', 'clipboard-write'], { origin });
	await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(SPECIAL_REF)}`,
		{ waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'explore');
	await expect(page.locator('#explore-resource-iri')).toHaveText(SPECIAL_REF);
	await page.locator('#explore-resource-card button[aria-label="Copy resource"]').click();
	await expect.poll(() => page.evaluate(() => navigator.clipboard.readText())).toBe(SPECIAL_REF);
	await captureScreenshot(page, 'native-chromium-clipboard-copy');
	await assertBrowserHealthy(page, health, 'native-chromium-clipboard-copy');
});

test('Remove previews fixed BNodes, then Add and Clear keep the selected BNode graph', async ({ page, request }) => {
	const health = monitorBrowser(page);
	const graphReference = `<_:${GRAPH_ID}>`;
	const sizeOfGraph = async () => Number(await (await request.get(
		`${REPOSITORY_URL}/size?context=${encodeURIComponent(graphReference)}`)).text());

	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'remove'), { waitUntil: 'domcontentloaded' });
	const removeForm = page.locator('#remove-form');
	await removeForm.locator('#subj').fill(SPECIAL_REF);
	await removeForm.locator('#pred').fill('<urn:bnr:predicate>');
	const removeGraph = removeForm.locator('select[name="context"]');
	await expect(removeGraph.locator(`option[value="${graphReference}"]`)).toHaveCount(1);
	await removeGraph.selectOption(graphReference);
	await expect(removeForm.locator('#remove-count')).toHaveText('1 statement matches', { timeout: 15000 });
	await removeForm.locator('#remove-preview-button').click();
	const removePreview = page.locator('#remove-preview');
	await expect(removePreview).toBeVisible();
	await expect(removePreview.locator('#remove-preview-status')).toHaveText('This statement would be removed.');
	await expect(removePreview.locator('tbody tr')).toHaveCount(1);
	await expect(removePreview.locator('tbody tr').first().locator('td[data-label="Subject"]')).toContainText(SPECIAL_REF);
	await expect(removePreview.locator('tbody tr').first().locator('td[data-label="Object"]')).toContainText('quoted');
	await expect(removePreview.locator('tbody tr').first().locator('td[data-label="Graph"]')).toContainText(graphReference);
	await expect.poll(sizeOfGraph).toBe(1);
	await captureScreenshot(page, 'remove-fixed-reference-preview');
	await removeForm.locator('button[type="submit"]').click();
	const removeDialog = page.getByRole('dialog');
	await expect(removeDialog).toBeVisible();
	await expect(removeDialog).toContainText('This permanently removes 1');
	await removeDialog.getByRole('button', { name: 'Remove statements' }).click();
	await waitForWriteDone(page, 'remove');
	await expect(removeForm.locator('.workbench-submit-status')).toHaveText('Removed 1 statement');
	await expect.poll(sizeOfGraph).toBe(0);

	// Add recreates this graph through the same fixed-reference form input after Remove emptied it.
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'add'), { waitUntil: 'domcontentloaded' });
	await page.locator('label[for="source-text"]').click();
	await page.locator('#Content-Type').selectOption('text/turtle');
	await page.locator('#text').fill('<urn:bnr:add-subject> <urn:bnr:predicate> "added through Add" .');
	await page.locator('#context').fill(graphReference);
	await page.locator('#add-upload-actions input[type="submit"]').click();
	await waitForWriteDone(page, 'add');
	await expect.poll(sizeOfGraph).toBe(1);

	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'clear'), { waitUntil: 'domcontentloaded' });
	const clearGraph = page.locator('#clear-form select[name="context"]');
	const graphOption = clearGraph.locator(`option[value="${graphReference}"]`);
	await expect(graphOption).toHaveCount(1);
	await expect(graphOption).toContainText(/1 statement/);
	await clearGraph.selectOption(graphReference);
	await page.locator('#clear-form button[type="submit"]').click();
	await page.getByRole('dialog', { name: 'Clear graph?' }).getByRole('button', { name: 'Clear graph' }).click();
	await waitForWriteDone(page, 'clear');
	await expect(page.locator('#clear-form .workbench-submit-status')).toHaveText('Graph cleared');
	await expect(clearGraph.locator(`option[value="${graphReference}"]`)).toHaveCount(0);
	await expect.poll(sizeOfGraph).toBe(0);
	await assertBrowserHealthy(page, health, 'remove-add-clear-fixed-graph');
});

test('a malformed Update reports an error without committing its earlier statements', async ({ page, request }) => {
	const health = monitorBrowser(page);
	const sizeBefore = Number(await (await request.get(`${REPOSITORY_URL}/size`)).text());
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'update'), { waitUntil: 'networkidle' });
	await page.locator('#update-editor .CodeMirror').waitFor({ state: 'visible' });
	await setQueryEditor(page, `INSERT DATA {
		<urn:bnr:must-not-appear> <urn:bnr:predicate> "partial" .
		<_:broken\\u00> <urn:bnr:predicate> "invalid" .
	}`);
	await page.locator('#update-form input[type="submit"]').click();
	await expect(page.locator('#update-form [role="alert"]')).not.toBeEmpty();
	await expect.poll(async () => Number(await (await request.get(`${REPOSITORY_URL}/size`)).text()))
		.toBe(sizeBefore);
	await assertBrowserHealthy(page, health, 'malformed-update', [{
		method: 'POST', pathSuffix: `/repositories/${REPOSITORY_ID}/update`, status: 400
	}]);
});

test('a malformed query is shown as a query result error', async ({ page }) => {
	const health = monitorBrowser(page);
	await openQueryPage(page, REPOSITORY_ID);
	await setQueryEditor(page, 'SELECT * WHERE { <_:broken\\u00> ?p ?o }');
	const response = page.waitForResponse(candidate => candidate.request().method() === 'POST'
		&& new URL(candidate.url()).pathname.endsWith(`/repositories/${REPOSITORY_ID}/query`));
	await page.locator('#exec').click();
	await response;
	await expect(page.locator('#query-results .query-result-error')).toBeVisible();
	await assertBrowserHealthy(page, health, 'malformed-query', [{
		method: 'POST', pathSuffix: `/repositories/${REPOSITORY_ID}/query`, status: 400
	}]);
});
